import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{execFileSync}from'node:child_process';import{fileURLToPath}from'node:url';
const R=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));
test('October 6 records two actual outputs and seven gaps',()=>{const b=R('assets/citizen-work.json'),d=b.deliveries.filter(x=>x.executionId==='daily-20261006-root');assert.deepEqual(d.map(x=>x.citizenId).sort(),['memoria','runo']);assert.ok(d.every(x=>x.review===null));const f=R('assets/research-frontiers.json');for(const id of ['saeon','nullroute','sigma','leimma','pharma','vox','cynosure'])for(const l of ['zh','en','ko'])assert.ok(f.citizens[id][l].some(x=>x.observationId===`2026-10-06-gap-${id}`&&!x.publicationId));});
test('attachment-only change reproduces current coverage gap, body control rejects',()=>{const r=JSON.parse(execFileSync(process.execPath,[fileURLToPath(new URL('./attachment-audit-20261006.mjs',import.meta.url))],{encoding:'utf8'}));assert.deepEqual(r.cases,R('research/2026-10-06/attachment-audit-results.json').cases);assert.equal(r.cases[1].errors.length,0);assert.ok(r.cases[2].errors.length>0);});
test('new publications retain translations, attachments and original archive dates',()=>{for(const id of ['runo','memoria']){const n=R(`research/2026-10-06/${id}.json`);for(const l of ['zh','en','ko'])assert.ok(n.title[l]&&n.lead[l]&&n.limitation[l]);for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}assert.equal(R('assets/energy-observatory.json').updatedAt,'2026-10-05');assert.equal(R('assets/weekly-learning.json').updated,'2026-10-05');});
